"""

cute_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

#include <cstdint>
#include <limits>

#include <cute/tensor.hpp>

using namespace cute;

template <int THREADS>
__global__ static void cute_layernorm_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    float* __restrict__ partial_stats,
    int* __restrict__ done_counter,
    int64_t outer,
    int64_t N,
    int blocks_per_row,
    int total_blocks,
    float eps,
    int use_vec)
{
  static_assert(THREADS % 32 == 0, "THREADS must be a multiple of warp size");

  const int tid = threadIdx.x;
  const int bid = blockIdx.x;
  const int64_t row = bid / blocks_per_row;
  const int part = bid - (int)(row * blocks_per_row);

  const int64_t N4 = N >> 2;

  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(outer, N),
      make_stride(N, Int<1>{})
  );
  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(N),
      make_stride(Int<1>{})
  );
  Tensor mB = make_tensor(
      make_gmem_ptr(B),
      make_shape(N),
      make_stride(Int<1>{})
  );
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(outer, N),
      make_stride(N, Int<1>{})
  );

  Tensor mX4 = make_tensor(
      make_gmem_ptr(reinterpret_cast<const float4*>(X)),
      make_shape(outer, N4),
      make_stride(N4, Int<1>{})
  );
  Tensor mW4 = make_tensor(
      make_gmem_ptr(reinterpret_cast<const float4*>(W)),
      make_shape(N4),
      make_stride(Int<1>{})
  );
  Tensor mB4 = make_tensor(
      make_gmem_ptr(reinterpret_cast<const float4*>(B)),
      make_shape(N4),
      make_stride(Int<1>{})
  );
  Tensor mY4 = make_tensor(
      make_gmem_ptr(reinterpret_cast<float4*>(Y)),
      make_shape(outer, N4),
      make_stride(N4, Int<1>{})
  );

  Tensor gPart = make_tensor(
      make_gmem_ptr(partial_stats),
      make_shape(outer, blocks_per_row, Int<2>{}),
      make_stride((int64_t)blocks_per_row * 2, Int<2>{}, Int<1>{})
  );

  float local_sum = 0.0f;
  float local_sumsq = 0.0f;

  const int64_t reduce_stride = (int64_t)blocks_per_row * THREADS;
  int64_t reduce_idx = (int64_t)part * THREADS + tid;

  if (use_vec != 0) {
    for (; reduce_idx < N4; reduce_idx += reduce_stride) {
      float4 xv = mX4(row, reduce_idx);
      local_sum += xv.x + xv.y + xv.z + xv.w;
      local_sumsq = fmaf(xv.x, xv.x, local_sumsq);
      local_sumsq = fmaf(xv.y, xv.y, local_sumsq);
      local_sumsq = fmaf(xv.z, xv.z, local_sumsq);
      local_sumsq = fmaf(xv.w, xv.w, local_sumsq);
    }
  } else {
    for (; reduce_idx < N; reduce_idx += reduce_stride) {
      float xv = mX(row, reduce_idx);
      local_sum += xv;
      local_sumsq = fmaf(xv, xv, local_sumsq);
    }
  }

  __shared__ float s_warp_sum[THREADS / 32];
  __shared__ float s_warp_sumsq[THREADS / 32];

  const int lane = tid & 31;
  const int warp = tid >> 5;

  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    local_sum += __shfl_down_sync(0xffffffffu, local_sum, offset);
    local_sumsq += __shfl_down_sync(0xffffffffu, local_sumsq, offset);
  }

  if (lane == 0) {
    s_warp_sum[warp] = local_sum;
    s_warp_sumsq[warp] = local_sumsq;
  }
  __syncthreads();

  if (warp == 0) {
    constexpr int NUM_WARPS = THREADS / 32;
    float block_sum = (lane < NUM_WARPS) ? s_warp_sum[lane] : 0.0f;
    float block_sumsq = (lane < NUM_WARPS) ? s_warp_sumsq[lane] : 0.0f;

    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      block_sum += __shfl_down_sync(0xffffffffu, block_sum, offset);
      block_sumsq += __shfl_down_sync(0xffffffffu, block_sumsq, offset);
    }

    if (lane == 0) {
      gPart(row, part, 0) = block_sum;
      gPart(row, part, 1) = block_sumsq;
    }
  }
  __syncthreads();

  // Lightweight global barrier. The host caps the grid at the number of
  // simultaneously resident blocks, so every block can reach this point.
  if (tid == 0) {
    __threadfence();
    atomicAdd(done_counter, 1);
    while (atomicAdd(done_counter, 0) < total_blocks) {
#if __CUDA_ARCH__ >= 700
      __nanosleep(64);
#endif
    }
    __threadfence();
  }
  __syncthreads();
  __threadfence();

  extern __shared__ float s_dynamic[];
  const int64_t partial_elems = outer * blocks_per_row;
  const size_t partial_storage_elems = (size_t)partial_elems * 2;

  float* s_partial_ptr = s_dynamic;
  float* s_row_ptr = s_dynamic + partial_storage_elems;

  Tensor sPart = make_tensor(
      make_smem_ptr(s_partial_ptr),
      make_shape(outer, blocks_per_row, Int<2>{}),
      make_stride((int64_t)blocks_per_row * 2, Int<2>{}, Int<1>{})
  );
  Tensor sRowStats = make_tensor(
      make_smem_ptr(s_row_ptr),
      make_shape(outer, Int<2>{}),
      make_stride(Int<2>{}, Int<1>{})
  );

  for (int64_t i = tid; i < partial_elems; i += THREADS) {
    int64_t r = i / blocks_per_row;
    int p = (int)(i - r * blocks_per_row);
    sPart(r, p, 0) = gPart(r, p, 0);
    sPart(r, p, 1) = gPart(r, p, 1);
  }
  __syncthreads();

  const float inv_n = 1.0f / (float)N;
  for (int64_t r = tid; r < outer; r += THREADS) {
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (int p = 0; p < blocks_per_row; ++p) {
      sum += sPart(r, p, 0);
      sumsq += sPart(r, p, 1);
    }

    float mean = sum * inv_n;
    float var = fmaf(-mean, mean, sumsq * inv_n);
    var = var < 0.0f ? 0.0f : var;

    sRowStats(r, 0) = mean;
    sRowStats(r, 1) = rsqrtf(var + eps);
  }
  __syncthreads();

  const int64_t write_stride = (int64_t)total_blocks * THREADS;
  int64_t write_idx = (int64_t)bid * THREADS + tid;

  if (use_vec != 0) {
    for (; write_idx < N4; write_idx += write_stride) {
      float4 wv = mW4(write_idx);
      float4 bv = mB4(write_idx);

      #pragma unroll 4
      for (int64_t r = 0; r < outer; ++r) {
        float mean = sRowStats(r, 0);
        float rstd = sRowStats(r, 1);
        float4 xv = mX4(r, write_idx);
        float4 yv;

        yv.x = fmaf((xv.x - mean) * rstd, wv.x, bv.x);
        yv.y = fmaf((xv.y - mean) * rstd, wv.y, bv.y);
        yv.z = fmaf((xv.z - mean) * rstd, wv.z, bv.z);
        yv.w = fmaf((xv.w - mean) * rstd, wv.w, bv.w);

        mY4(r, write_idx) = yv;
      }
    }
  } else {
    for (; write_idx < N; write_idx += write_stride) {
      float wv = mW(write_idx);
      float bv = mB(write_idx);

      #pragma unroll 4
      for (int64_t r = 0; r < outer; ++r) {
        float mean = sRowStats(r, 0);
        float rstd = sRowStats(r, 1);
        float xv = mX(r, write_idx);
        mY(r, write_idx) = fmaf((xv - mean) * rstd, wv, bv);
      }
    }
  }
}

torch::Tensor cute_layernorm_forward(torch::Tensor x,
                                     torch::Tensor weight,
                                     torch::Tensor bias,
                                     double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
  TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(weight.dim() > 0, "normalized_shape must not be empty");
  TORCH_CHECK(x.dim() >= weight.dim(), "x must have at least normalized_shape dimensions");
  TORCH_CHECK(bias.sizes() == weight.sizes(), "bias and weight shapes must match");

  for (int i = 0; i < weight.dim(); ++i) {
    int x_dim = x.dim() - weight.dim() + i;
    TORCH_CHECK(x.size(x_dim) == weight.size(i),
                "The trailing dimensions of x must match normalized_shape");
  }

  c10::cuda::CUDAGuard device_guard(x.device());

  auto x_c = x.contiguous();
  auto weight_c = weight.contiguous();
  auto bias_c = bias.contiguous();

  const int64_t N = weight_c.numel();
  TORCH_CHECK(N > 0, "normalized_shape must contain at least one element");
  TORCH_CHECK(x_c.numel() % N == 0, "x numel must be divisible by normalized numel");
  const int64_t outer = x_c.numel() / N;
  TORCH_CHECK(outer > 0, "x must not be empty");

  auto y = torch::empty_like(x_c);

  float* x_ptr = x_c.data_ptr<float>();
  float* w_ptr = weight_c.data_ptr<float>();
  float* b_ptr = bias_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  auto aligned16 = [](const void* p) {
    return (reinterpret_cast<uintptr_t>(p) & 0xF) == 0;
  };

  const bool use_vec =
      ((N & 3) == 0) &&
      aligned16(x_ptr) &&
      aligned16(w_ptr) &&
      aligned16(b_ptr) &&
      aligned16(y_ptr);

  constexpr int THREADS = 256;
  constexpr int MAX_BLOCKS_PER_ROW = 32;
  constexpr int64_t TARGET_ELEMS_PER_BLOCK = THREADS * 4 * 8;

  int64_t target64 = (N + TARGET_ELEMS_PER_BLOCK - 1) / TARGET_ELEMS_PER_BLOCK;
  int target_blocks_per_row = target64 > MAX_BLOCKS_PER_ROW
                                  ? MAX_BLOCKS_PER_ROW
                                  : (target64 < 1 ? 1 : (int)target64);

  int device_index = 0;
  cudaError_t err = cudaGetDevice(&device_index);
  TORCH_CHECK(err == cudaSuccess, "cudaGetDevice failed: ", cudaGetErrorString(err));

  cudaDeviceProp prop{};
  err = cudaGetDeviceProperties(&prop, device_index);
  TORCH_CHECK(err == cudaSuccess, "cudaGetDeviceProperties failed: ",
              cudaGetErrorString(err));

  int blocks_per_row = 0;
  int max_resident_blocks = 0;
  size_t dynamic_smem_bytes = 0;

  for (int candidate = target_blocks_per_row; candidate >= 1; --candidate) {
    size_t smem = sizeof(float) *
                  ((size_t)outer * (size_t)candidate * 2 + (size_t)outer * 2);

    int blocks_per_sm = 0;
    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm,
        cute_layernorm_kernel<THREADS>,
        THREADS,
        smem
    );
    TORCH_CHECK(err == cudaSuccess,
                "cudaOccupancyMaxActiveBlocksPerMultiprocessor failed: ",
                cudaGetErrorString(err));

    int64_t resident = (int64_t)prop.multiProcessorCount * blocks_per_sm;
    if (resident >= outer && (int64_t)candidate <= resident / outer) {
      blocks_per_row = candidate;
      max_resident_blocks = (int)resident;
      dynamic_smem_bytes = smem;
      break;
    }
  }

  TORCH_CHECK(blocks_per_row > 0,
              "Unable to select a resident grid configuration for LayerNorm");

  const int64_t total_blocks64 = outer * blocks_per_row;
  TORCH_CHECK(total_blocks64 <= max_resident_blocks,
              "LayerNorm grid exceeds resident block capacity");
  TORCH_CHECK(total_blocks64 <= std::numeric_limits<int>::max(),
              "LayerNorm grid is too large");
  const int total_blocks = (int)total_blocks64;

  const int64_t stats_elems = outer * blocks_per_row * 2;
  auto workspace = torch::empty({stats_elems + 1}, x.options());
  float* stats_ptr = workspace.data_ptr<float>();
  int* done_ptr = reinterpret_cast<int*>(stats_ptr + stats_elems);

  cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();
  err = cudaMemsetAsync(done_ptr, 0, sizeof(int), stream);
  TORCH_CHECK(err == cudaSuccess, "LayerNorm barrier initialization failed: ",
              cudaGetErrorString(err));

  dim3 grid((unsigned)total_blocks);
  dim3 block(THREADS);

  cute_layernorm_kernel<THREADS><<<grid, block, dynamic_smem_bytes, stream>>>(
      x_ptr,
      w_ptr,
      b_ptr,
      y_ptr,
      stats_ptr,
      done_ptr,
      outer,
      N,
      blocks_per_row,
      total_blocks,
      (float)eps,
      use_vec ? 1 : 0
  );

  err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE LayerNorm kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cute_cpp_decl,
    cuda_sources=cute_cuda_src,
    functions=["cute_layernorm_forward"],
    extra_cflags=["-O3", "-std=c++17"],
    extra_cuda_cflags=["-O3", "-std=c++17"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single custom CUTE/CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm_forward(
            x,
            self.ln.weight,
            self.ln.bias,
            self.ln.eps,
        )

